5	
6	/**
7	 * An invoice as a project's list shows it: every stored {@link Invoice} field plus the money already
8	 * settled against it ({@code paid}, the sum of its {@link Payment}s) and how much is still owed
9	 * ({@code due} = discounted amount - paid). The paid/due split is derived per request in
10	 * {@link InvoicesGet} rather than stored, so it always reflects the current payments. Additive over
11	 * the raw invoice shape — existing readers keep using {@code amount}; the new ones read {@code due}.
12	 *
13	 * What is OWED is the invoice's percentage discount applied on top of the stored {@code amount} (the
14	 * subtotal), the same figure the invoice's discount breakdown shows — so the discount flows through
15	 * everywhere money owed is surfaced (the invoice row's due, the client statement, the dashboard
16	 * outstanding total). The stored {@code amount} itself is left as the face (pre-discount) figure.
17	 *
18	 * The {@code status} is likewise DERIVED from the payments rather than flipped by hand: once some
19	 * (but not all) of the amount is paid it reads {@code PARTIAL}, once the amount is covered it reads
20	 * {@code PAID}; with nothing paid it stays at the invoice's stored lifecycle stage (DRAFT/SENT).
21	 * See {@link #deriveStatus}.
22	 */
23	public class ProjectInvoice {
24	
25	    private final Long id;
26	    private final Long projectId;
27	    private final BigDecimal amount;
28	    private final String status;
29	    private final String issuedDate;
30	    private final String dueDate;
31	    private final BigDecimal paid;
32	    private final BigDecimal due;
33	
34	    public ProjectInvoice(Invoice invoice, BigDecimal paid) {
35	        BigDecimal owed = owedAmount(invoice.getAmount(), invoice.getDiscountPct());
36	        this.id = invoice.getId();
37	        this.projectId = invoice.getProjectId();
38	        this.amount = invoice.getAmount();
39	        this.status = deriveStatus(invoice.getStatus(), owed, paid);
40	        this.issuedDate = invoice.getIssuedDate();
41	        this.dueDate = invoice.getDueDate();
42	        this.paid = paid;
43	        this.due = owed.subtract(paid);
44	    }
45	
46	    /**
47	     * What a client actually owes for an invoice: the stored {@code amount} (the subtotal, before any
48	     * discount) less the percentage discount taken off it. The discount is {@code amount * pct / 100}
49	     * rounded to the cent, matching {@link InvoiceDiscount}, so the invoice's due, the statement and
50	     * the dashboard all agree with the invoice's discount breakdown. A null amount or percentage is
51	     * treated as zero.
52	     */
53	    static BigDecimal owedAmount(BigDecimal amount, BigDecimal discountPct) {
54	        BigDecimal amt = amount == null ? BigDecimal.ZERO : amount;
55	        BigDecimal pct = discountPct == null ? BigDecimal.ZERO : discountPct;
56	        BigDecimal discount = amt.multiply(pct)
57	                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
58	        return amt.subtract(discount);
