3	import java.util.List;
4	import java.util.Map;
5	import java.util.function.Function;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 */
19	@Profile("harness")
20	@RestController
21	@RequestMapping("/__test__")
22	public class TestSupportController {
23	
24	    private final Audit audit;
25	    private final JdbcTemplate jdbc;
26	
27	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
28	        this.audit = audit;
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * Every domain table, child-before-parent. Referential integrity is dropped around the
34	     * TRUNCATE so the order is only for readability of the FK chain (invoices -> projects ->
35	     * clients). Add a new table here (and a matching {@code seedTable} call) to extend the harness.
36	     */
37	    private static final List<String> TABLES =
38	            List.of("invoice_payments", "invoice_line_items", "invoices", "notes", "tasks",
39	                    "contacts", "project_tags", "projects", "tags", "clients", "app_settings");
40	
41	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
42	    @PostMapping("/reset")
43	    public void reset() {
44	        audit.clear();
45	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
46	        for (String table : TABLES) {
47	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
48	        }
49	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
50	    }
51	
52	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
53	    @PostMapping("/seed")
54	    public void seed(@RequestBody Map<String, Object> fixture) {
55	        seedTable(fixture, "clients", "INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
56	                c -> new Object[] {id(c, "id"), c.get("name"), c.get("email")});
57	        seedTable(fixture, "projects",
58	                "INSERT INTO projects (id, name, client_id, status, archived, budget, code)"
59	                        + " VALUES (?, ?, ?, ?, ?, ?, ?)",
60	                p -> new Object[] {id(p, "id"), p.get("name"), id(p, "clientId"),
61	                        p.getOrDefault("status", "ACTIVE"), Boolean.TRUE.equals(p.get("archived")),
62	                        p.get("budget") == null ? null : ((Number) p.get("budget")).doubleValue(),
63	                        p.get("code")});
64	        seedTable(fixture, "contacts",
65	                "INSERT INTO contacts (id, name, email, role, client_id, is_primary)"
66	                        + " VALUES (?, ?, ?, ?, ?, ?)",
67	                c -> new Object[] {id(c, "id"), c.get("name"), c.get("email"), c.get("role"),
68	                        id(c, "clientId"), Boolean.TRUE.equals(c.get("primary"))});
69	        seedTable(fixture, "tasks", "INSERT INTO tasks (id, title, done, project_id) VALUES (?, ?, ?, ?)",
70	                t -> new Object[] {id(t, "id"), t.get("title"), Boolean.TRUE.equals(t.get("done")),
71	                        id(t, "projectId")});
72	        seedTable(fixture, "notes",
73	                "INSERT INTO notes (id, target_type, target_id, note_text, noted_at) VALUES (?, ?, ?, ?, ?)",
74	                n -> new Object[] {id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
75	                        n.get("at")});
76	        // Notes are pre-seeded AND created through the API in the same spec, so the identity has to
77	        // continue past the seeded ids (a raw insert of an explicit id does not advance H2's
78	        // GENERATED BY DEFAULT sequence — the next app insert would otherwise collide on id=1).
79	        restartIdentity("notes");
80	        seedTable(fixture, "tags", "INSERT INTO tags (id, name) VALUES (?, ?)",
81	                t -> new Object[] {id(t, "id"), t.get("name")});
82	        seedTable(fixture, "projectTags",
83	                "INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
84	                pt -> new Object[] {id(pt, "projectId"), id(pt, "tagId")});
85	        seedInvoices(fixture);
86	        seedTable(fixture, "payments",
87	                "INSERT INTO invoice_payments (id, invoice_id, amount, paid_on) VALUES (?, ?, ?, ?)",
88	                p -> new Object[] {id(p, "id"), id(p, "invoiceId"),
89	                        ((Number) p.get("amount")).doubleValue(), p.get("date")});
90	        // Payments are pre-seeded AND created through the API in the same spec, so the identity has
91	        // to continue past the seeded ids (a raw insert of an explicit id does not advance H2's
92	        // GENERATED BY DEFAULT sequence — the next app insert would otherwise collide on id=1).
93	        restartIdentity("invoice_payments");
94	        // The dashboard's reference date for "overdue", a top-level scalar (not a table of rows) so
95	        // the count is deterministic. Absent = the dashboard falls back to today.
96	        Object asOf = fixture.get("asOf");
97	        if (asOf != null) {
98	            jdbc.update("INSERT INTO app_settings (setting_key, setting_value) VALUES ('asOf', ?)",
99	                    asOf.toString());
100	        }
101	    }
102	
103	    /**
104	     * Seed invoices and, nested under each, its line items. An invoice's amount is the sum of its
105	     * lines' qty * unitPrice, so when a fixture lists {@code lineItems} the amount is derived from
106	     * them (the user no longer types one figure); a fixture may still give an explicit
107	     * {@code amount} instead (an invoice with no lines). One method rather than a plain seedTable
108	     * call because the line items live inside each invoice, keyed by the invoice's own id.
109	     */
110	    @SuppressWarnings("unchecked")
111	    private void seedInvoices(Map<String, Object> fixture) {
112	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
113	        if (invoices == null) {
114	            return;
115	        }
116	        for (Map<String, Object> invoice : invoices) {
117	            seedInvoice(invoice);
118	        }
119	    }
120	
121	    /** Insert one invoice row and, under it, its line items. */
122	    @SuppressWarnings("unchecked")
123	    private void seedInvoice(Map<String, Object> invoice) {
124	        long invoiceId = id(invoice, "id");
125	        List<Map<String, Object>> lineItems = (List<Map<String, Object>>) invoice.get("lineItems");
126	        jdbc.update("INSERT INTO invoices"
127	                + " (id, project_id, amount, status, issued_date, due_date, discount_pct, tax_pct)"
128	                + " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
129	                invoiceId, id(invoice, "projectId"), invoiceAmount(invoice, lineItems),
130	                invoice.getOrDefault("status", "DRAFT"), invoice.get("issuedDate"),
131	                invoice.get("dueDate"), pct(invoice, "discountPct"), pct(invoice, "taxPct"));
132	        seedLineItems(invoiceId, lineItems);
133	    }
134	
135	    /**
136	     * An invoice's stored amount: an explicit {@code amount} when the fixture gives one (an invoice
137	     * with no lines), otherwise the sum of its line items' qty * unitPrice.
138	     */
139	    private static double invoiceAmount(Map<String, Object> invoice,
140	            List<Map<String, Object>> lineItems) {
141	        if (invoice.get("amount") != null) {
142	            return ((Number) invoice.get("amount")).doubleValue();
143	        }
144	        double amount = 0.0;
145	        if (lineItems != null) {
146	            for (Map<String, Object> line : lineItems) {
147	                amount += ((Number) line.get("qty")).doubleValue()
148	                        * ((Number) line.get("unitPrice")).doubleValue();
149	            }
150	        }
151	        return amount;
152	    }
153	
154	    /** Insert an invoice's line items (absent list = none). */
155	    private void seedLineItems(long invoiceId, List<Map<String, Object>> lineItems) {
156	        if (lineItems == null) {
157	            return;
158	        }
159	        for (Map<String, Object> line : lineItems) {
